            WriteNumMap(w, "fund_wage_support", x.FundWageSupport);
            w.WriteStartArray("bankruptcies");
            foreach (Bankruptcy item in x.Bankruptcies) { WriteBankruptcy(w, item); }
            w.WriteEndArray();
            WriteNumMap(w, "sales_receipts", x.SalesReceipts);
            WriteNumMap(w, "producer_purchases", x.ProducerPurchases);
            WriteNumMap(w, "construction_wages", x.ConstructionWages);
            WriteNumMap(w, "labor_migrated", x.LaborMigrated);
            w.WriteStartArray("exits");
            foreach (ExitRecord item in x.Exits) { WriteExitRecord(w, item); }
            w.WriteEndArray();
            w.WriteEndObject();
        }

